package com.neuroflow.goal.entity;
import com.neuroflow.subject.entity.Subject;import com.neuroflow.user.entity.User;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;import lombok.Getter;import lombok.Setter;
@Getter @Setter @Entity @Table(name="goals", indexes=@Index(name="idx_goals_user_period", columnList="user_id,start_date,end_date"))
public class Goal { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id") private Subject subject; @Column(name="goal_type",nullable=false,length=50) private String goalType; @Column(name="target_value",nullable=false,precision=10,scale=2) private BigDecimal targetValue; @Column(nullable=false,length=30) private String unit; @Column(name="start_date",nullable=false) private LocalDate startDate; @Column(name="end_date",nullable=false) private LocalDate endDate; @Column(nullable=false,length=30) private String status; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; }
